CREATE TABLE t1(a,b,c PRIMARY KEY) WITHOUT ROWID; CREATE INDEX t1a ON t1(a) WHERE a IS NOT NULL; CREATE INDEX t1b ON t1(b) WHERE b>10; WITH RECURSIVE nums(value) AS (VALUES(1) UNION ALL SELECT value+1 FROM nums WHERE value<20) INSERT INTO t1(a,b,c) SELECT CASE WHEN value%3!=0 THEN value END, value, value FROM nums; ANALYZE; UPDATE t1 SET a=b; ANALYZE; UPDATE t1 SET a=NULL WHERE b%3!=0; UPDATE t1 SET b=b+100; ANALYZE; UPDATE t1 SET a=CASE WHEN b%3!=0 THEN b END; UPDATE t1 SET b=b-100; ANALYZE; DELETE FROM t1 WHERE b BETWEEN 8 AND 12; ANALYZE; REINDEX; ANALYZE;